60: 	size_t         len; /* of payload */
61: 	unsigned char *ptr; /* in payload */
62: 	union {
63: 		struct nlattr     nla;
64: 		char              buf[NLA_HDRLEN];   /* align */
65: 	}              u;
66: 	unsigned char  payload[];
67: } nlamsgbuf_t;
