401: 	int r;
402: 
403: 	while ((a = nla_getattr(g)) != NULL) {
404: 		r = parser(a, arg);
405: 		free(a);
406: 		if (r < 0) {
407: 			fido_log_debug("%s: parser", __func__);
408: 			return (-1);
409: 		}
410: 	}
