553: 		return (0);
554: 	}
555: 	if (nla_get_u32(a, t->value) < 0) {
556: 		fido_log_debug("%s: target", __func__);
557: 		return (-1);
558: 	}
559: 	t->found = 1;
560: 
561: 	return (0);
562: }
