609: static int
610: unpack_hmac_secret(fido_blob_t *blob,
611:     const WEBAUTHN_HMAC_SECRET_SALT *pHmacSecret)
612: {
613: 	if (pHmacSecret == NULL || pHmacSecret->cbFirst == 0 ||
614: 	    pHmacSecret->pbFirst == NULL) {
615: 		fido_log_debug("%s: hmac-secret absent", __func__);
616: 		return 0; /* proceed without hmac-secret */
617: 	}
618: 	if (!fido_blob_is_empty(blob)) {
619: 		fido_log_debug("%s: fido_blob_is_empty", __func__);
620: 		return -1;
621: 	}
622: 	if (fido_blob_set(blob, pHmacSecret->pbFirst,
623: 	    pHmacSecret->cbFirst) < 0) {
624: 		fido_log_debug("%s: fido_blob_set", __func__);
625: 		return -1;
626: 	}
627: 	if (pHmacSecret->cbSecond != 0 && pHmacSecret->pbSecond != NULL &&
628: 	    fido_blob_append(blob, pHmacSecret->pbSecond,
629: 	    pHmacSecret->cbSecond) < 0) {
630: 		fido_log_debug("%s: fido_blob_append", __func__);
631: 		return -1;
632: 	}
633: 
634: 	return 0;
635: }
