661: static int
662: translate_fido_assert(struct winhello_assert *ctx, const fido_assert_t *assert,
663:     const char *pin, int ms)
664: {
665: 	WEBAUTHN_AUTHENTICATOR_GET_ASSERTION_OPTIONS *opt;
666: 
667: 	/* not supported by webauthn.h */
668: 	if (assert->up == FIDO_OPT_FALSE) {
669: 		fido_log_debug("%s: up %d", __func__, assert->up);
670: 		return FIDO_ERR_UNSUPPORTED_OPTION;
671: 	}
672: 	if ((ctx->rp_id = to_utf16(assert->rp_id)) == NULL) {
673: 		fido_log_debug("%s: rp_id", __func__);
674: 		return FIDO_ERR_INTERNAL;
675: 	}
676: 	if (pack_cd(&ctx->cd, &assert->cd) < 0) {
677: 		fido_log_debug("%s: pack_cd", __func__);
678: 		return FIDO_ERR_INTERNAL;
679: 	}
680: 	/* options */
681: 	opt = &ctx->opt;
682: 	opt->dwVersion = WEBAUTHN_AUTHENTICATOR_GET_ASSERTION_OPTIONS_VERSION_1;
683: 	opt->dwTimeoutMilliseconds = ms < 0 ? MAXMSEC : (DWORD)ms;
684: 	if (pack_appid(opt, assert->appid, &ctx->appid) < 0) {
685: 		fido_log_debug("%s: pack_appid" , __func__);
686: 		return FIDO_ERR_INTERNAL;
687: 	}
688: 	if (pack_credlist(&opt->CredentialList, &assert->allow_list) < 0) {
689: 		fido_log_debug("%s: pack_credlist", __func__);
690: 		return FIDO_ERR_INTERNAL;
691: 	}
692: 	if (pack_assert_ext(opt, &assert->ext) < 0) {
693: 		fido_log_debug("%s: pack_assert_ext", __func__);
694: 		return FIDO_ERR_UNSUPPORTED_EXTENSION;
695: 	}
696: 	if (set_assert_uv(&opt->dwUserVerificationRequirement, assert->uv,
697: 	    pin) < 0) {
698: 		fido_log_debug("%s: set_assert_uv", __func__);
699: 		return FIDO_ERR_INTERNAL;
700: 	}
701: 
702: 	return FIDO_OK;
703: }
