705: static int
706: translate_winhello_assert(fido_assert_t *assert,
707:     const struct winhello_assert *ctx)
708: {
709: 	const WEBAUTHN_ASSERTION *wa = ctx->assert;
710: 	const WEBAUTHN_AUTHENTICATOR_GET_ASSERTION_OPTIONS *opt = &ctx->opt;
711: 	int r;
